vec3 vrchAdjustHue(vec3 color, float angle) {
  const mat3 toYiq = mat3(0.299, 0.587, 0.114, 0.596, -0.275, -0.321, 0.212, -0.523, 0.311);
  const mat3 toRgb = mat3(1.0, 0.956, 0.621, 1.0, -0.272, -0.647, 1.0, -1.106, 1.703);
  vec3 yiq = toYiq * color;
  float hue = atan(yiq.z, yiq.y) + angle;
  float chroma = length(yiq.yz);
  return clamp(toRgb * vec3(yiq.x, chroma * cos(hue), chroma * sin(hue)), 0.0, 1.0);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec2 px = vec2(uParam_blur) / iResolution.xy;
  vec4 center = vrchSampleSource0(uv);
  vec4 blurred = center;
  blurred += vrchSampleSource0(uv + vec2(px.x, 0.0));
  blurred += vrchSampleSource0(uv - vec2(px.x, 0.0));
  blurred += vrchSampleSource0(uv + vec2(0.0, px.y));
  blurred += vrchSampleSource0(uv - vec2(0.0, px.y));
  blurred += vrchSampleSource0(uv + px);
  blurred += vrchSampleSource0(uv - px);
  blurred += vrchSampleSource0(uv + vec2(px.x, -px.y));
  blurred += vrchSampleSource0(uv + vec2(-px.x, px.y));
  blurred /= 9.0;
  float blurMix = smoothstep(0.0, 0.5, uParam_blur);
  vec4 source = mix(center, blurred, blurMix);
  vec3 color = source.rgb * uParam_brightness;
  color = (color - 0.5) * uParam_contrast + 0.5;
  float luma = dot(color, vec3(0.2126, 0.7152, 0.0722));
  color = mix(vec3(luma), color, uParam_saturate);
  color = vrchAdjustHue(color, radians(uParam_hue_rotate));
  color = mix(color, vec3(1.0) - color, uParam_invert);
  vec3 sepia = vec3(dot(color, vec3(0.393, 0.769, 0.189)), dot(color, vec3(0.349, 0.686, 0.168)), dot(color, vec3(0.272, 0.534, 0.131)));
  color = mix(color, sepia, uParam_sepia);
  fragColor = vec4(clamp(color, 0.0, 1.0), clamp(source.a * uParam_opacity, 0.0, 1.0));
}
